import{_ as t,a0 as o,w as r,s as d,ao as e,I as i,a1 as p,A as l,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"使用 Elixir 语言编写一个小游戏 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Elixir 语言编写一个小游戏 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Elixir 语言编写一个小游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Elixir 语言编写一个小游戏 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20201209 Program a simple game with Elixir","title":"使用 Elixir 语言编写一个小游戏","tag":"202104","desc":""},"relativePath":"202104/20201209 Program a simple game with Elixir.md","filePath":"[post].md"}'),u={name:"202104/20201209 Program a simple game with Elixir.md"};function g(m,s,x,T,f,h){const a=o("Link");return r(),d("div",null,[s[25]||(s[25]=e('<h1 id="使用-elixir-语言编写一个小游戏" tabindex="-1">使用 Elixir 语言编写一个小游戏 <a class="header-anchor" href="#使用-elixir-语言编写一个小游戏" aria-label="Permalink to “使用 Elixir 语言编写一个小游戏”">​</a></h1><blockquote><p>通过编写“猜数字”游戏来学习 Elixir 编程语言，并将它与一个你熟知的语言做对比。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/12/223351t68886wmza1m9jnt.jpg" alt=""></p><p>为了更好的学习一门新的编程语言，最好的方法是去关注主流语言的一些共有特征：</p><ul><li>变量</li><li>表达式</li><li>语句</li></ul><p>这些概念是大多数编程语言的基础。因为这些相似性，只要你通晓了一门编程语言，你可以通过对比差异来熟知另一门编程语言。</p><p>另外一个学习新编程语言的好方法是开始编写一个简单标准的程序。它可以让你集中精力在语言上而非程序的逻辑本身。在这个系列的文章中，我们使用“猜数字”程序来实现，在这个程序中，计算机会选择一个介于 1 到 100 之间的数字，并要求你来猜测它。程序会循环执行，直到你正确猜出该数字为止。</p><p>“猜数字”这个程序使用了编程语言的以下概念：</p><ul><li>变量</li><li>输入</li><li>输出</li><li>条件判断</li><li>循环</li></ul><p>这是一个学习新编程语言的绝佳实践。</p><h3 id="猜数字的-elixir-实现" tabindex="-1">猜数字的 Elixir 实现 <a class="header-anchor" href="#猜数字的-elixir-实现" aria-label="Permalink to “猜数字的 Elixir 实现”">​</a></h3>',11)),i("p",null,[p(a,{href:"https://elixir-lang.org/"},{default:l(()=>[...s[0]||(s[0]=[n("Elixir",-1)])]),_:1}),s[2]||(s[2]=n(" 是一门被设计用于构建稳定可维护应用的动态类型的函数式编程语言。它与 ",-1)),p(a,{href:"https://www.erlang.org/"},{default:l(()=>[...s[1]||(s[1]=[n("Erlang",-1)])]),_:1}),s[3]||(s[3]=n(" 运行于同一虚拟机之上，吸纳了 Erlang 的众多长处的同时拥有更加简单的语法。",-1))]),s[26]||(s[26]=e(`<p>你可以编写一个 Elixir 版本的“猜数字”游戏来体验这门语言。</p><p>这是我的实现方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>defmodule Guess do</span></span>
<span class="line"><span>  def guess() do</span></span>
<span class="line"><span>     random = Enum.random(1..100)</span></span>
<span class="line"><span>     IO.puts &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span>     Guess.guess_loop(random)</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>  def guess_loop(num) do</span></span>
<span class="line"><span>    data = IO.read(:stdio, :line)</span></span>
<span class="line"><span>    {guess, _rest} = Integer.parse(data)</span></span>
<span class="line"><span>    cond do</span></span>
<span class="line"><span>      guess &lt; num -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;Too low!&quot;</span></span>
<span class="line"><span>        guess_loop(num)</span></span>
<span class="line"><span>      guess &gt; num -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;Too high!&quot;</span></span>
<span class="line"><span>        guess_loop(num)</span></span>
<span class="line"><span>      true -&gt;</span></span>
<span class="line"><span>        IO.puts &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Guess.guess()</span></span></code></pre></div><p>Elixir 通过列出变量的名称后面跟一个 <code>=</code> 号来为了给变量分配一个值。举个例子，表达式 <code>random = 0</code> 给 <code>random</code> 变量分配一个数值 0。</p><p>代码以定义一个模块开始。在 Elixir 语言中，只有模块可以包含命名函数。</p><p>紧随其后的这行代码定义了入口函数 <code>guess()</code>，这个函数：</p><ul><li>调用 <code>Enum.random()</code> 函数来获取一个随机整数</li><li>打印游戏提示</li><li>调用循环执行的函数</li></ul><p>剩余的游戏逻辑实现在 <code>guess_loop()</code> 函数中。</p>`,8)),i("p",null,[s[5]||(s[5]=i("code",null,"guess_loop()",-1)),s[6]||(s[6]=n(" 函数利用 ",-1)),p(a,{href:"https://en.wikipedia.org/wiki/Tail_call"},{default:l(()=>[...s[4]||(s[4]=[n("尾递归",-1)])]),_:1}),s[7]||(s[7]=n(" 来实现循环。Elixir 中有好几种实现循环的方法，尾递归是比较常用的一种方式。",-1)),s[8]||(s[8]=i("code",null,"guess_loop()",-1)),s[9]||(s[9]=n(" 函数做的最后一件事就是调用自身。",-1))]),s[27]||(s[27]=e(`<p><code>guess_loop()</code> 函数的第一行读取用户输入。下一行调用 <code>parse()</code> 函数将输入转换成一个整数。</p><p><code>cond</code> 表达式是 Elixir 版本的多重分支表达式。与其他语言中的 <code>if/elif</code> 或者 <code>if/elsif</code> 表达式不同，Elixir 对于的首个分支或者最后一个没有分支并没有区别对待。</p><p>这个 <code>cond</code> 表达式有三路分支：猜测的结果可以比随机数大、小或者相等。前两个选项先输出不等式的方向然后递归调用 <code>guess_loop()</code>，循环返回至函数开始。最后一个选项输出 <code>That&#39;s right</code>，然后这个函数就完成了。</p><h3 id="输出例子" tabindex="-1">输出例子 <a class="header-anchor" href="#输出例子" aria-label="Permalink to “输出例子”">​</a></h3><p>现在你已经编写了你的 Elixir 代码，你可以运行它来玩“猜数字”的游戏。每次你执行这个程序，Elixir 会选择一个不同的随机数，你可以一直猜下去直到你找到正确的答案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ elixir guess.exs</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>30</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>20</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>14</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>“猜数字”游戏是一个学习一门新编程语言的绝佳入门程序，因为它用了非常直接的方法实践了常用的几个编程概念。通过用不同语言实现这个简单的小游戏，你可以实践各个语言的核心概念并且比较它们的细节。</p><p>你是否有你最喜爱的编程语言？你将怎样用它来编写“猜数字”这个游戏？关注这个系列的文章来看看其他你可能感兴趣的语言实现。</p><hr>`,9)),i("p",null,[s[11]||(s[11]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/20/12/elixir"},{default:l(()=>[...s[10]||(s[10]=[n("https://opensource.com/article/20/12/elixir",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/moshez"},{default:l(()=>[...s[12]||(s[12]=[n("Moshe Zadka",-1)])]),_:1}),s[17]||(s[17]=n(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),p(a,{href:"https://github.com/tt67wq"},{default:l(()=>[...s[14]||(s[14]=[n("tt67wq",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const c=t(u,[["render",g]]);export{k as __pageData,c as default};
